input.command:
set -e; cd /tmp/rt
node -e '
const y=require("/home/user/workspace/repo/node_modules/.pnpm/node_modules/yaml");const fs=require("fs");
const s=y.parse(fs.readFileSync("/home/user/workspace/repo/.github/workflows/release.yml","utf8")).jobs.release.steps;
fs.writeFileSync("pick.sh",s[1].run);fs.writeFileSync("notes.sh",s[4].run)' 
mkdir -p bin; printf '#!/bin/sh\ngit rev-parse HEAD\n' > bin/gh; chmod +x bin/gh; export PATH=$PWD/bin:$PATH
run() { export GITHUB_OUTPUT=out; : > out; bash -e pick.sh; cat out; }
echo "--- first run"; run; v=$(sed -n 's/version=//p' out)
git tag "v$v" HEAD~1
echo "--- new commit since release, same day"; run; v2=$(sed -n 's/version=//p' out)
echo "--- notes"; SHA=$(git rev-parse HEAD) VERSION=$v2 IMAGE=img bash -c 'gh(){ echo "gh $1 $2 $3 ${@: -1}"; }; source notes.sh'
git tag "v$v2" HEAD
echo "--- nothing new"; run

